 1	import path from 'node:path';
 2	import { ts } from '@ts-morph/common';
 3	
 4	export interface SourceImport {
 5	  file: string;
 6	  line: number;
 7	  specifier: string;
 8	  target?: string;
 9	  kind: 'value' | 'type';
10	}
11	
12	/** Static relative imports and re-exports, resolved against the same immutable source snapshot. */
13	export function maintenanceImports(source: ts.SourceFile, files: ReadonlyMap<string, string>): SourceImport[] {
14	  const imports: SourceImport[] = [];
15	  const host: ts.ModuleResolutionHost = {
16	    fileExists: (file) => files.has(path.posix.normalize(file).replace(/^\//, '')),
17	    readFile: (file) => files.get(path.posix.normalize(file).replace(/^\//, '')),
18	  };
19	  for (const node of source.statements) {
20	    if (!ts.isImportDeclaration(node) && !ts.isExportDeclaration(node)) continue;
21	    const literal = node.moduleSpecifier;
22	    if (!literal || !ts.isStringLiteral(literal)) continue;
23	    const specifier = literal.text;
24	    const typeOnly = ts.isImportDeclaration(node) ? node.importClause?.isTypeOnly === true : node.isTypeOnly;
25	    const resolved = specifier.startsWith('.')
26	      ? ts.resolveModuleName(
27	          specifier,
28	          '/' + source.fileName,
29	          { allowJs: true, moduleResolution: ts.ModuleResolutionKind.Node10 },
30	          host,
31	        ).resolvedModule
32	      : undefined;
33	    imports.push({
34	      file: source.fileName,
35	      line: source.getLineAndCharacterOfPosition(node.getStart(source)).line + 1,
36	      specifier,
37	      kind: typeOnly ? 'type' : 'value',
38	      ...(resolved ? { target: resolved.resolvedFileName.replace(/^\//, '') } : {}),
39	    });
40	  }
41	  return imports;
42	}

