 14	interface CoverageEntry {
 15	  sourceHash?: unknown;
 16	  coverage?: {
 17	    statementMap?: Record<
 18	      string,
 19	      { start?: { line?: number; column?: number }; end?: { line?: number; column?: number } }
 20	    >;
 21	    s?: Record<string, number>;
 22	  };
