 41	/** Current bytes, independent of the age or availability of a compiler index. */
 42	export function analyzeSourceFunctions(file: string, source: string): FunctionAnalysis {
 43	  const sourceFile = ts.createSourceFile(file, source, ts.ScriptTarget.Latest, true);
 44	  const diagnostics =
 45	    (sourceFile as ts.SourceFile & { parseDiagnostics?: readonly ts.Diagnostic[] }).parseDiagnostics ?? [];
 46	  const errors = diagnostics.map((diagnostic) => {
 47	    const line = sourceFile.getLineAndCharacterOfPosition(diagnostic.start ?? 0).line + 1;
 48	    return `${file}:${line}: ${ts.flattenDiagnosticMessageText(diagnostic.messageText, ' ')}`;
 49	  });
 50	  const functions: SourceFunction[] = [];
 51	  function visit(node: ts.Node, owners: readonly string[]): void {
 52	    if (isImplementedFunction(node)) {
 53	      const name = functionName(node, sourceFile);
 54	      const identity = [...owners, name];
 55	      functions.push(measureFunction(node, sourceFile, identity.join('.')));
 56	      ts.forEachChild(node, (child) => visit(child, identity));
 57	      return;
 58	    }
 59	    const owner =
 60	      (ts.isClassDeclaration(node) || ts.isClassExpression(node)) && node.name
 61	        ? node.name.text
 62	        : ts.isVariableDeclaration(node) && node.initializer && !isImplementedFunction(node.initializer)
 63	          ? node.name.getText(sourceFile)
 64	          : ts.isModuleDeclaration(node)
 65	            ? node.name.getText(sourceFile)
 66	            : null;
 67	    ts.forEachChild(node, (child) => visit(child, owner ? [...owners, owner] : owners));
 68	  }
 69	  if (errors.length === 0) visit(sourceFile, []);
 70	  return { sourceFile, functions, errors };
 71	}
 72	
 73	type ImplementedFunction = ts.FunctionLikeDeclaration & { body: ts.ConciseBody };
 74	
 75	function isImplementedFunction(node: ts.Node): node is ImplementedFunction {
 76	  return ts.isFunctionLike(node) && 'body' in node && Boolean(node.body);
 77	}
 78	
 79	function functionName(node: ImplementedFunction, file: ts.SourceFile): string {
 80	  if (ts.isConstructorDeclaration(node)) return 'constructor';
 81	  if (ts.isGetAccessor(node)) return `get ${node.name.getText(file)}`;
 82	  if (ts.isSetAccessor(node)) return `set ${node.name.getText(file)}`;
 83	  if (node.name) return node.name.getText(file);
 84	  const parent = node.parent;
 85	  if (ts.isVariableDeclaration(parent) || ts.isPropertyAssignment(parent) || ts.isPropertyDeclaration(parent)) {
 86	    return parent.name.getText(file);
 87	  }
 88	  if (ts.isCallExpression(parent)) {
 89	    return `<callback:${parent.expression.getText(file)}:${parent.arguments.indexOf(node as ts.Expression)}>`;
 90	  }
 91	  const position = file.getLineAndCharacterOfPosition(node.getStart(file));
 92	  return `<anonymous@${position.line + 1}:${position.character + 1}>`;
 93	}
 94	
 95	function measureFunction(node: ImplementedFunction, file: ts.SourceFile, name: string): SourceFunction {
 96	  const contributions: ComplexityContribution[] = [];
 97	  const calls = new Set<string>();
 98	  const add = (at: ts.Node, kind: string, cyclomatic: number, cognitive: number): void => {
 99	    const position = file.getLineAndCharacterOfPosition(at.getStart(file));
100	    contributions.push({ line: position.line + 1, column: position.character + 1, kind, cyclomatic, cognitive });
101	  };
102	  function visit(current: ts.Node, nesting: number): void {
103	    if (current !== node && isImplementedFunction(current)) return;
104	    if (ts.isIfStatement(current)) {
105	      const elseIf = ts.isIfStatement(current.parent) && current.parent.elseStatement === current;
106	      add(current, elseIf ? 'else-if' : 'if', 1, elseIf ? 1 : nesting + 1);
107	      visit(current.expression, nesting);
108	      visit(current.thenStatement, nesting + 1);
109	      if (current.elseStatement) {
110	        if (!ts.isIfStatement(current.elseStatement)) add(current.elseStatement, 'else', 0, 1);
111	        visit(current.elseStatement, ts.isIfStatement(current.elseStatement) ? nesting : nesting + 1);
112	      }
113	      return;
114	    }
115	    if (isLoop(current) || ts.isCatchClause(current) || ts.isConditionalExpression(current)) {
116	      add(current, ts.SyntaxKind[current.kind], 1, nesting + 1);
117	      ts.forEachChild(current, (child) => visit(child, nesting + 1));
118	      return;
119	    }
120	    if (ts.isSwitchStatement(current)) {
121	      add(current, 'switch', 0, nesting + 1);
122	      visit(current.expression, nesting);
123	      visit(current.caseBlock, nesting + 1);
124	      return;
125	    }
126	    if (ts.isCaseClause(current)) add(current, 'case', 1, 0);
127	    if (ts.isBinaryExpression(current) && isShortCircuit(current.operatorToken.kind)) {
128	      const operator = current.operatorToken.kind;
129	      const parent = unwrapLogicalParent(current);
130	      const continuesSequence = ts.isBinaryExpression(parent) && parent.operatorToken.kind === operator;
131	      add(
132	        current.operatorToken,
133	        ts.tokenToString(operator) ?? 'logical',
134	        1,
135	        operator === ts.SyntaxKind.QuestionQuestionToken || continuesSequence ? 0 : 1,
136	      );
137	    }
138	    if ((ts.isBreakStatement(current) || ts.isContinueStatement(current)) && current.label) {
139	      add(current, 'labeled-jump', 0, 1);
140	    }
141	    if (ts.isCallExpression(current)) {
142	      const called = current.expression.getText(file);
143	      calls.add(called);
144	    }
145	    ts.forEachChild(current, (child) => visit(child, nesting));
146	  }
147	  visit(node.body, 0);
148	  const startOffset = node.getStart(file);
149	  const endOffset = node.getEnd();
150	  const tokens = implementationTokens(node, file);
151	  return {
152	    name,
153	    file: file.fileName,
154	    startLine: file.getLineAndCharacterOfPosition(startOffset).line + 1,
155	    endLine: file.getLineAndCharacterOfPosition(endOffset - 1).line + 1,
156	    startOffset,
157	    endOffset,
158	    sourceHash: sourceHash(file.text.slice(startOffset, endOffset)),
159	    bodyHash: sourceHash(tokens.exact.join('\n')),
160	    renamedBodyHash: sourceHash(tokens.renamed.join('\n')),
161	    tokenCount: tokens.exact.length,
162	    cyclomatic: 1 + contributions.reduce((sum, item) => sum + item.cyclomatic, 0),
163	    cognitive: contributions.reduce((sum, item) => sum + item.cognitive, 0),
164	    contributions,
165	    calls: [...calls].sort(),
166	  };
167	}
168	
169	function isLoop(node: ts.Node): boolean {
170	  return (
171	    ts.isForStatement(node) ||
172	    ts.isForInStatement(node) ||
173	    ts.isForOfStatement(node) ||
174	    ts.isWhileStatement(node) ||
175	    ts.isDoStatement(node)
176	  );
177	}
178	
179	function isShortCircuit(kind: ts.SyntaxKind): boolean {
180	  return (
181	    kind === ts.SyntaxKind.AmpersandAmpersandToken ||
182	    kind === ts.SyntaxKind.BarBarToken ||
183	    kind === ts.SyntaxKind.QuestionQuestionToken
184	  );
185	}
186	
187	function unwrapLogicalParent(node: ts.Node): ts.Node {
188	  let parent = node.parent;
189	  while (ts.isParenthesizedExpression(parent)) parent = parent.parent;
190	  return parent;
191	}
192	
193	/** Preserve literals and property names; renaming is candidate evidence, never behavioral equivalence. */
194	function implementationTokens(node: ImplementedFunction, file: ts.SourceFile): { exact: string[]; renamed: string[] } {
195	  const bindings = new Map<string, string>();
196	  const bind = (name: ts.BindingName): void => {
197	    if (ts.isIdentifier(name)) {
198	      if (!bindings.has(name.text)) bindings.set(name.text, `local:${bindings.size}`);
199	    } else for (const element of name.elements) if (ts.isBindingElement(element)) bind(element.name);
200	  };
201	  for (const parameter of node.parameters) bind(parameter.name);
202	  const collect = (current: ts.Node): void => {
203	    if (isImplementedFunction(current)) return;
204	    if (ts.isVariableDeclaration(current)) bind(current.name);
205	    ts.forEachChild(current, collect);
206	  };
207	  collect(node.body);
208	  const exact: string[] = [];
209	  const renamed: string[] = [];
210	  const visit = (current: ts.Node): void => {
211	    const children = current.getChildren(file);
212	    if (children.length > 0) {
213	      for (const child of children) visit(child);
214	      return;
215	    }
216	    const text = current.getText(file);
217	    if (!text) return;
218	    exact.push(`${current.kind}:${text}`);
219	    const parent = current.parent;
220	    const propertyName =
221	      ts.isShorthandPropertyAssignment(parent) ||
222	      (ts.isBindingElement(parent) && parent.propertyName === current) ||
223	      (ts.isPropertyAccessExpression(parent) && parent.name === current) ||
224	      ((ts.isPropertyAssignment(parent) || ts.isMethodDeclaration(parent)) && parent.name === current);
225	    const value = ts.isIdentifier(current) && !propertyName ? (bindings.get(text) ?? text) : text;
226	    renamed.push(`${current.kind}:${value}`);
227	  };
228	  visit(node.body);
229	  return { exact, renamed };
230	}

