 13	export interface FindingSite {
 14	  file: string;
 15	  line: number;
 16	  name?: string;
 17	}
 18	export interface SourceFinding {
 19	  id: string;
 20	  rule: 'complexity' | 'duplication' | 'dependency-cycle' | 'architecture' | 'crap' | 'broken-dependency';
 21	  evidence: 'derived' | 'candidate';
 22	  summary: string;
 23	  sites: FindingSite[];
 24	  score: number;
 25	  details: string[];
 26	  status?: 'introduced' | 'worsened' | 'existing' | 'resolved' | 'uncomparable';
