 29	export interface MeasuredFunction extends SourceFunction {
 30	  coverage: FunctionCoverage;
 31	}
 32	export interface SourceAnalysis {
 33	  functions: MeasuredFunction[];
 34	  findings: SourceFinding[];
 35	  imports: SourceImport[];
 36	  graph: Map<string, Set<string>>;
 37	  problems: string[];
 38	}
