 40	export const SOURCE_ANALYSIS_LIMITS = [
 41	  `TS/JS implemented functions; metric rules ${FUNCTION_METRIC_RULES}. Cognitive counts structural nesting and logical sequences; recursion and interprocedural behavior are not measured.`,
 42	  'Duplication compares whole function body tokens (at least 60 tokens), retaining literals and property names. Renamed local bindings are candidates; similarity does not prove interchangeable behavior or justify deletion.',
 43	  'Dependencies cover static relative imports and re-exports, including type imports. Package aliases, CommonJS, dynamic imports, runtime handoffs, and other languages require indexed evidence or source inspection.',
 44	  'Ownership and mixed responsibilities require evidence about callers, state and business rules; this scan does not infer a correct owner or an architectural grade.',
 45	];
 46	
 47	export function analyzeSourceSnapshot(
 48	  snapshot: SourceSnapshot,
 49	  coverage: ReviewCoverage = { files: {}, problem: 'No source-matched coverage supplied.' },
 50	  architecture?: ArchitectureConfig,
 51	): SourceAnalysis {
 52	  const functions: MeasuredFunction[] = [];
 53	  const imports: SourceImport[] = [];
 54	  const problems = [...snapshot.problems];
 55	  for (const [file, source] of snapshot.files) {
 56	    const analysis = analyzeSourceFunctions(file, source);
 57	    problems.push(...analysis.errors);
 58	    if (analysis.errors.length > 0) continue;
 59	    functions.push(
 60	      ...analysis.functions.map((fn) => ({
 61	        ...fn,
 62	        coverage: functionCoverage(fn, analysis.functions, source, coverage),
 63	      })),
 64	    );
 65	    imports.push(...maintenanceImports(analysis.sourceFile, snapshot.files));
 66	  }
 67	  const graph = new Map([...snapshot.files.keys()].map((file) => [file, new Set<string>()]));
 68	  for (const imported of imports) if (imported.target) graph.get(imported.file)!.add(imported.target);
 69	  const findings = [
 70	    ...complexityFindings(functions),
 71	    ...duplicateFindings(functions),
 72	    ...cycleFindings(graph, imports),
 73	  ];
 74	  const rules = analyzeArchitectureGraph(graph, [...snapshot.files.keys()], architecture);
 75	  for (const edge of rules.forbiddenEdges) {
 76	    // The architecture analyzer owns rule interpretation; use its complete edge evidence.
 77	    findings.push({
 78	      id: `architecture:${edge.from}:${edge.to}`,
 79	      rule: 'architecture',
 80	      evidence: 'derived',
 81	      summary: `${edge.from} → ${edge.to}: ${edge.fileEdgeCount} file dependencies violate the declared rule.`,
 82	      sites: edge.examples.map((example) => ({
 83	        file: example.fromFile,
 84	        line: imports.find((item) => item.file === example.fromFile && item.target === example.toFile)?.line ?? 1,
 85	      })),
 86	      score: edge.fileEdgeCount,
 87	      details: edge.examples.map((example) => `${example.fromFile} → ${example.toFile}`),
 88	    });
 89	  }
 90	  return { functions, findings: findings.sort(compareFindings), imports, graph, problems };
 91	}
 92	
 93	function complexityFindings(functions: readonly MeasuredFunction[]): SourceFinding[] {
 94	  const findings: SourceFinding[] = [];
 95	  for (const fn of functions) {
 96	    const site = { file: fn.file, line: fn.startLine, name: fn.name };
 97	    if (fn.cyclomatic > 10 || fn.cognitive > 15)
 98	      findings.push({
 99	        id: `complexity:${fn.file}:${fn.name}`,
100	        rule: 'complexity',
101	        evidence: 'derived',
102	        summary: `${fn.name}: cyclomatic ${fn.cyclomatic}, cognitive ${fn.cognitive}.`,
103	        sites: [site],
104	        score: Math.max(fn.cyclomatic / 10, fn.cognitive / 15),
105	        details: [
106	          'Review branching and nesting while preserving decisions, effects, and error handling.',
107	          ...fn.contributions
108	            .filter((part) => part.cognitive > 1)
109	            .map((part) => `${fn.file}:${part.line}:${part.column} ${part.kind}: +${part.cognitive} cognitive`),
110	        ],
111	      });
112	    if (fn.coverage.status === 'available' && fn.coverage.crap! >= 30)
113	      findings.push({
114	        id: `crap:${fn.file}:${fn.name}`,
115	        rule: 'crap',
116	        evidence: 'derived',
117	        score: fn.coverage.crap!,
118	        sites: [site],
119	        summary: `${fn.name}: CRAP ${fn.coverage.crap}, measured line coverage ${Math.round(fn.coverage.fraction! * 100)}%.`,
120	        details: [
121	          'CRAP = cyclomatic² × (1 − measured coverage)³ + cyclomatic. Improve tests and simplify behavior where justified.',
122	        ],
123	      });
124	  }
125	  return findings;
126	}
127	
128	function duplicateFindings(functions: readonly MeasuredFunction[]): SourceFinding[] {
129	  const groups = new Map<string, MeasuredFunction[]>();
130	  for (const fn of functions) {
131	    if (fn.tokenCount < 60) continue;
132	    const key = fn.renamedBodyHash;
133	    const group = groups.get(key) ?? [];
134	    group.push(fn);
135	    groups.set(key, group);
136	  }
137	  return [...groups.values()]
138	    .filter((group) => group.length > 1)
139	    .map((group) => {
140	      const exact = new Set(group.map((fn) => fn.bodyHash)).size === 1;
141	      const sites = group.map((fn) => ({ file: fn.file, line: fn.startLine, name: fn.name }));
142	      return {
143	        id: `duplication:${group[0]!.renamedBodyHash}`,
144	        rule: 'duplication' as const,
145	        evidence: 'candidate' as const,
146	        summary: `${group.length} functions share ${exact ? 'identical body tokens' : 'body tokens after local binding renaming'}.`,
147	        sites,
148	        score: group.length,
149	        details: [
150	          `${group[0]!.tokenCount} tokens per body; comments and whitespace excluded; literals retained.`,
151	          'Read both contracts and callers. If these implementations own the same rule, reuse one owner; otherwise retain the separate responsibilities.',
152	        ],
153	      };
154	    });
155	}
156	
157	function cycleFindings(graph: Map<string, Set<string>>, imports: readonly SourceImport[]): SourceFinding[] {
158	  return stronglyConnectedComponents(graph)
159	    .components.filter((members) => members.length > 1 || graph.get(members[0]!)?.has(members[0]!))
160	    .map((members) => {
161	      const files = new Set(members);
162	      const edges = imports.filter((edge) => files.has(edge.file) && edge.target && files.has(edge.target));
163	      return {
164	        id: `dependency-cycle:${[...members].sort().join('|')}`,
165	        rule: 'dependency-cycle' as const,
166	        evidence: 'derived' as const,
167	        summary: `${members.length} file(s) form a circular static dependency component.`,
168	        score: members.length,
