 47	/** Read immutable blobs in one batch, including paths containing spaces or newlines. */
 48	export function baseSourceSnapshot(projectRoot: string, base: string, opts: SourceScanOptions = {}): SourceSnapshot {
 49	  const revision = gitRevision(projectRoot, base);
 50	  const entries = git(projectRoot, ['ls-tree', '-r', '-z', revision]).toString('utf8').split('\0').filter(Boolean);
 51	  const blobs = new Map<string, string>();
 52	  for (const entry of entries) {
 53	    const match = /^(100\d+) blob ([a-f0-9]+)\t([\s\S]+)$/.exec(entry);
 54	    if (match) blobs.set(match[3]!, match[2]!);
 55	  }
 56	  const selected = [...blobs.keys()]
 57	    .filter((file) => eligibleMaintenanceFile(file, opts.includeTests))
 58	    .sort()
 59	    .slice(0, opts.maxFiles ?? SOURCE_SCAN_DEFAULTS.maxFiles);
 60	  const contents = new Map<string, string>();
 61	  // Batches bound peak memory independently of the repository's total object size.
 62	  for (let offset = 0; offset < selected.length; offset += 32) {
 63	    const batch = selected.slice(offset, offset + 32);
 64	    const sizes = git(
 65	      projectRoot,
 66	      ['cat-file', '--batch-check'],
 67	      batch.map((file) => blobs.get(file)).join('\n') + '\n',
 68	    )
 69	      .toString('utf8')
 70	      .trim()
 71	      .split('\n');
 72	    const readable = batch.filter(
 73	      (_, index) => Number(sizes[index]?.split(' ')[2]) <= (opts.maxFileBytes ?? SOURCE_SCAN_DEFAULTS.maxFileBytes),
 74	    );
 75	    if (readable.length === 0) continue;
 76	    const output = git(projectRoot, ['cat-file', '--batch'], readable.map((file) => blobs.get(file)).join('\n') + '\n');
 77	    let cursor = 0;
 78	    for (const file of readable) {
 79	      const headerEnd = output.indexOf(10, cursor);
 80	      const size = Number(output.subarray(cursor, headerEnd).toString('utf8').split(' ')[2]);
 81	      if (headerEnd < 0 || !Number.isSafeInteger(size) || size < 0 || headerEnd + 1 + size > output.length) {
 82	        throw new Error('Invalid Git blob response while reading review base');
 83	      }
 84	      contents.set(file, output.subarray(headerEnd + 1, headerEnd + 1 + size).toString('utf8'));
 85	      cursor = headerEnd + 1 + size + 1;
 86	    }
 87	  }
 88	  return collectSnapshot(revision, [...blobs.keys()], opts, (file) => {
 89	    const content = contents.get(file);
 90	    if (content === undefined) throw new Error('exceeds the per-file byte limit');
 91	    return content;
 92	  });
 93	}
