 95	export function assertSourceSnapshotCurrent(
 96	  projectRoot: string,
 97	  snapshot: SourceSnapshot,
 98	  opts: SourceScanOptions = {},
 99	): string[] {
100	  const paths = presentProjectFiles(projectRoot)
101	    .filter((file) => eligibleMaintenanceFile(file, opts.includeTests))
102	    .sort();
103	  const problems: string[] = [];
104	  if (
105	    paths.length !== snapshot.eligibleFiles ||
106	    paths.slice(0, opts.maxFiles ?? SOURCE_SCAN_DEFAULTS.maxFiles).some((file) => !snapshot.files.has(file))
107	  ) {
108	    problems.push('Eligible source file set changed or was incomplete during analysis; rerun after edits settle.');
109	  }
110	  for (const [file, content] of snapshot.files) {
111	    try {
112	      if (
113	        readProjectFile(projectRoot, file, {
114	          maxBytes: opts.maxFileBytes ?? SOURCE_SCAN_DEFAULTS.maxFileBytes,
115	        }).toString('utf8') !== content
116	      ) {
117	        problems.push(`${file}: source changed during analysis; rerun after edits settle.`);
118	      }
119	    } catch {
120	      problems.push(`${file}: source unavailable during final freshness check.`);
121	    }
122	  }
123	  return problems;
124	}
