126	function collectSnapshot(
127	  revision: string,
128	  paths: string[],
129	  opts: SourceScanOptions,
130	  read: (file: string) => string,
131	): SourceSnapshot {
132	  const eligible = paths.filter((file) => eligibleMaintenanceFile(file, opts.includeTests)).sort();
133	  const files = new Map<string, string>();
134	  const problems: string[] = [];
135	  const selected = eligible.slice(0, opts.maxFiles ?? SOURCE_SCAN_DEFAULTS.maxFiles);
136	  if (selected.length < eligible.length)
137	    problems.push(
138	      `${eligible.length - selected.length} eligible files omitted by max-files; increase --max-files to cover them.`,
139	    );
140	  let bytes = 0;
141	  for (const file of selected) {
142	    try {
143	      const content = read(file);
144	      bytes += Buffer.byteLength(content);
145	      if (bytes > MAX_SNAPSHOT_BYTES) {
146	        problems.push(
147	          `Snapshot exceeds ${MAX_SNAPSHOT_BYTES} bytes; ${selected.length - files.size} remaining files omitted.`,
148	        );
149	        break;
150	      }
151	      files.set(file, content);
152	    } catch (error) {
153	      problems.push(`${file}: ${error instanceof Error ? error.message : String(error)}`);
154	    }
155	  }
156	  return {
157	    revision,
158	    files,
159	    fingerprint: sourceHash(
160	      [...files].map(([file, content]) => `${JSON.stringify(file)}:${sourceHash(content)}`).join('\n'),
161	    ),
162	    eligibleFiles: eligible.length,
163	    excludedFiles: paths.length - eligible.length,
164	    problems,
165	  };
166	}
