108	export function changedFunctions(
109	  before: readonly MeasuredFunction[],
110	  after: readonly MeasuredFunction[],
111	): FunctionChange[] {
112	  const key = (fn: MeasuredFunction): string => `${fn.file}:${fn.name}`;
113	  const grouped = (functions: readonly MeasuredFunction[]): Map<string, MeasuredFunction[]> => {
114	    const result = new Map<string, MeasuredFunction[]>();
115	    for (const fn of functions) result.set(key(fn), [...(result.get(key(fn)) ?? []), fn]);
116	    return result;
117	  };
118	  const old = grouped(before);
119	  const next = grouped(after);
120	  const changes: FunctionChange[] = [];
121	  for (const name of [...new Set([...old.keys(), ...next.keys()])].sort()) {
122	    const previous = old.get(name) ?? [];
123	    const current = next.get(name) ?? [];
124	    if (previous.length > 1 || current.length > 1) {
125	      if (previous.map((fn) => fn.sourceHash).join() !== current.map((fn) => fn.sourceHash).join()) {
126	        changes.push(
127	          ...previous.map((fn) => ({ status: 'uncomparable' as const, before: fn })),
128	          ...current.map((fn) => ({ status: 'uncomparable' as const, after: fn })),
129	        );
130	      }
131	    } else if (previous[0] && current[0]) {
132	      if (previous[0].sourceHash !== current[0].sourceHash)
133	        changes.push({
134	          status: 'modified',
135	          before: previous[0],
136	          after: current[0],
137	          delta: {
138	            cyclomatic: current[0].cyclomatic - previous[0].cyclomatic,
139	            cognitive: current[0].cognitive - previous[0].cognitive,
140	          },
141	        });
142	    } else if (current[0]) changes.push({ status: 'added', after: current[0] });
143	    else if (previous[0]) changes.push({ status: 'removed', before: previous[0] });
144	  }
145	  return changes;
146	}
