148	function compareSourceFindings(
149	  before: SourceAnalysis,
150	  after: SourceAnalysis,
151	  changed: Set<string>,
152	  comparable: boolean,
153	): SourceFinding[] {
154	  const old = new Map(before.findings.map((finding) => [finding.id, finding]));
155	  const next = new Map(after.findings.map((finding) => [finding.id, finding]));
156	  const findings: SourceFinding[] = [];
157	  const ambiguous = ambiguousFunctionNames(before.functions, after.functions);
158	  for (const finding of after.findings) {
159	    if (finding.sites.length && !finding.sites.some((site) => changed.has(site.file))) continue;
160	    const previous = old.get(finding.id);
161	    const status =
162	        !comparable || finding.rule === 'crap' || finding.sites.some((site) => ambiguous.has(`${site.file}:${site.name}`))
163	        ? 'uncomparable'
164	        : !previous
165	          ? 'introduced'
166	          : finding.score > previous.score
167	            ? 'worsened'
168	            : 'existing';
169	    findings.push({ ...finding, status });
170	  }
171	  for (const finding of before.findings)
172	    if (!next.has(finding.id) && finding.sites.some((site) => changed.has(site.file))) {
173	      findings.push({ ...finding, status: comparable ? 'resolved' : 'uncomparable' });
174	    }
