 30	export function loadReviewCoverage(projectRoot: string, file?: string): ReviewCoverage {
 31	  if (!file) return { files: {}, problem: 'No source-matched coverage artifact supplied.' };
 32	  try {
 33	    const parsed = JSON.parse(readProjectFile(projectRoot, file).toString('utf8')) as {
 34	      schemaVersion?: unknown;
 35	      files?: unknown;
 36	    };
 37	    if (
 38	      parsed.schemaVersion !== 1 ||
 39	      !parsed.files ||
 40	      typeof parsed.files !== 'object' ||
 41	      Array.isArray(parsed.files)
 42	    ) {
 43	      return {
 44	        files: {},
 45	        problem: 'Expected a version 1 source-matched coverage artifact; use scripts/record-review-coverage.mjs.',
 46	      };
 47	    }
 48	    return { files: parsed.files as Record<string, CoverageEntry> };
 49	  } catch (error) {
 50	    return { files: {}, problem: `Cannot read coverage: ${error instanceof Error ? error.message : String(error)}` };
