 53	
 54	export function functionCoverage(
 55	  fn: SourceFunction,
 56	  peers: readonly SourceFunction[],
 57	  source: string,
 58	  input: ReviewCoverage,
 59	): FunctionCoverage {
 60	  const unavailable = (reason: string): FunctionCoverage => ({ status: 'unavailable', reason });
 61	  if (input.problem) return unavailable(input.problem);
 62	  const entry = input.files[fn.file];
 63	  if (!entry || entry.sourceHash !== sourceHash(source))
 64	    return unavailable('Coverage missing or source hash does not match current bytes.');
 65	  const { statementMap, s } = entry.coverage ?? {};
 66	  if (!statementMap || !s || typeof statementMap !== 'object' || typeof s !== 'object')
 67	    return unavailable('Malformed statement coverage.');
 68	  const lines = new Map<number, boolean>();
 69	  const offsets = [0];
 70	  for (let offset = 0; offset < source.length; offset++) if (source[offset] === '\n') offsets.push(offset + 1);
 71	  for (const [id, span] of Object.entries(statementMap)) {
 72	    const line = span?.start?.line;
 73	    const column = span?.start?.column;
 74	    const count = s[id];
 75	    if (
 76	      !Number.isInteger(line) ||
 77	      !Number.isInteger(column) ||
 78	      line! < 1 ||
 79	      line! > offsets.length ||
 80	      column! < 0 ||
 81	      !Number.isFinite(count) ||
 82	      count! < 0
 83	    )
 84	      return unavailable('Malformed statement coverage locations or counts.');
 85	    const start = offsets[line! - 1]! + column!;
 86	    if (start < fn.startOffset || start >= fn.endOffset) continue;
 87	    if (
 88	      peers.some(
 89	        (peer) =>
 90	          peer !== fn &&
 91	          peer.startOffset > fn.startOffset &&
 92	          peer.endOffset <= fn.endOffset &&
 93	          start >= peer.startOffset &&
 94	          start < peer.endOffset,
 95	      )
 96	    )
 97	      continue;
 98	    lines.set(line!, (lines.get(line!) ?? false) || count! > 0);
 99	  }
100	  if (lines.size === 0) return unavailable('No measured executable lines in this function.');
101	  const coveredLines = [...lines.values()].filter(Boolean).length;
102	  const fraction = coveredLines / lines.size;
103	  return {
104	    status: 'available',
105	    basis: 'istanbul-statement-start-lines',
106	    coveredLines,
107	    measuredLines: lines.size,
108	    fraction,
109	    crap: Number((fn.cyclomatic ** 2 * (1 - fraction) ** 3 + fn.cyclomatic).toFixed(2)),
110	  };
111	}

