 47	export function analyzeSourceSnapshot(
 48	  snapshot: SourceSnapshot,
 49	  coverage: ReviewCoverage = { files: {}, problem: 'No source-matched coverage supplied.' },
 50	  architecture?: ArchitectureConfig,
 51	): SourceAnalysis {
 52	  const functions: MeasuredFunction[] = [];
 53	  const imports: SourceImport[] = [];
 54	  const problems = [...snapshot.problems];
 55	  for (const [file, source] of snapshot.files) {
 56	    const analysis = analyzeSourceFunctions(file, source);
 57	    problems.push(...analysis.errors);
 58	    if (analysis.errors.length > 0) continue;
 59	    functions.push(
 60	      ...analysis.functions.map((fn) => ({
 61	        ...fn,
 62	        coverage: functionCoverage(fn, analysis.functions, source, coverage),
 63	      })),
 64	    );
 65	    imports.push(...maintenanceImports(analysis.sourceFile, snapshot.files));
 66	  }
 67	  const graph = new Map([...snapshot.files.keys()].map((file) => [file, new Set<string>()]));
 68	  for (const imported of imports) if (imported.target) graph.get(imported.file)!.add(imported.target);
 69	  const findings = [
 70	    ...complexityFindings(functions),
 71	    ...duplicateFindings(functions),
 72	    ...cycleFindings(graph, imports),
 73	  ];
 74	  const rules = analyzeArchitectureGraph(graph, [...snapshot.files.keys()], architecture);
 75	  for (const edge of rules.forbiddenEdges) {
 76	    // The architecture analyzer owns rule interpretation; use its complete edge evidence.
 77	    findings.push({
 78	      id: `architecture:${edge.from}:${edge.to}`,
 79	      rule: 'architecture',
 80	      evidence: 'derived',
 81	      summary: `${edge.from} → ${edge.to}: ${edge.fileEdgeCount} file dependencies violate the declared rule.`,
 82	      sites: edge.examples.map((example) => ({
 83	        file: example.fromFile,
 84	        line: imports.find((item) => item.file === example.fromFile && item.target === example.toFile)?.line ?? 1,
 85	      })),
 86	      score: edge.fileEdgeCount,
 87	      details: edge.examples.map((example) => `${example.fromFile} → ${example.toFile}`),
 88	    });
 89	  }
 90	  return { functions, findings: findings.sort(compareFindings), imports, graph, problems };
 91	}
