 93	function complexityFindings(functions: readonly MeasuredFunction[]): SourceFinding[] {
 94	  const findings: SourceFinding[] = [];
 95	  for (const fn of functions) {
 96	    const site = { file: fn.file, line: fn.startLine, name: fn.name };
 97	    if (fn.cyclomatic > 10 || fn.cognitive > 15)
 98	      findings.push({
 99	        id: `complexity:${fn.file}:${fn.name}`,
100	        rule: 'complexity',
101	        evidence: 'derived',
102	        summary: `${fn.name}: cyclomatic ${fn.cyclomatic}, cognitive ${fn.cognitive}.`,
103	        sites: [site],
104	        score: Math.max(fn.cyclomatic / 10, fn.cognitive / 15),
105	        details: [
106	          'Review branching and nesting while preserving decisions, effects, and error handling.',
107	          ...fn.contributions
108	            .filter((part) => part.cognitive > 1)
109	            .map((part) => `${fn.file}:${part.line}:${part.column} ${part.kind}: +${part.cognitive} cognitive`),
110	        ],
111	      });
112	    if (fn.coverage.status === 'available' && fn.coverage.crap! >= 30)
113	      findings.push({
114	        id: `crap:${fn.file}:${fn.name}`,
115	        rule: 'crap',
116	        evidence: 'derived',
117	        score: fn.coverage.crap!,
118	        sites: [site],
119	        summary: `${fn.name}: CRAP ${fn.coverage.crap}, measured line coverage ${Math.round(fn.coverage.fraction! * 100)}%.`,
120	        details: [
121	          'CRAP = cyclomatic² × (1 − measured coverage)³ + cyclomatic. Improve tests and simplify behavior where justified.',
122	        ],
123	      });
124	  }
125	  return findings;
126	}
