157	function cycleFindings(graph: Map<string, Set<string>>, imports: readonly SourceImport[]): SourceFinding[] {
158	  return stronglyConnectedComponents(graph)
159	    .components.filter((members) => members.length > 1 || graph.get(members[0]!)?.has(members[0]!))
160	    .map((members) => {
161	      const files = new Set(members);
162	      const edges = imports.filter((edge) => files.has(edge.file) && edge.target && files.has(edge.target));
163	      return {
164	        id: `dependency-cycle:${[...members].sort().join('|')}`,
165	        rule: 'dependency-cycle' as const,
166	        evidence: 'derived' as const,
167	        summary: `${members.length} file(s) form a circular static dependency component.`,
168	        score: members.length,
169	        sites: edges.map((edge) => ({ file: edge.file, line: edge.line })),
170	        details: edges.map((edge) => `${edge.file}:${edge.line} → ${edge.target} (${edge.kind} import)`),
171	      };
172	    });
173	}
